import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, fix a base {base} > 1. Consider positive real numbers x, y, z that satisfy the system: log_{base}({k1} x^{m} y^{n}) − (log_{base} x)(log_{base} y) = {c1}; log_{base}({k2} y^{n} z^{p}) − (log_{base} y)(log_{base} z) = {c2}; log_{base}({k3} z^{p} x^{m}) − (log_{base} z)(log_{base} x) = {c3}. The system has exactly two solutions (x1, y1, z1) and (x2, y2, z2). Compute the value of y1*y2.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters ensuring a symmetric, solvable system with two distinct positive solutions.
# Structure:
# (log_b(k1) + m*u + n*v - u*v = c1) -> (u - n)(v - m) = A > 0
# (log_b(k2) + n*v + p*w - v*w = c2) -> (v - p)(w - n) = B > 0
# (log_b(k3) + p*w + m*u - w*u = c3) -> (w - m)(u - p) = C > 0
# Choose A,B,C > 0 and make k1,k2,k3 integer powers of b to keep the instance clean.
for _ in range(1000):
    base = rng.randint(2, 9)
    m = rng.randint(1, 4)
    n = rng.randint(1, 4)
    p = rng.randint(1, 4)
    A = rng.randint(1, 9)
    B = rng.randint(1, 9)
    C = rng.randint(1, 9)
    # Choose integer exponents for k1,k2,k3
    E1 = rng.randint(0, 6)
    E2 = rng.randint(0, 6)
    E3 = rng.randint(0, 6)
    # Solve for c1,c2,c3 so that A,B,C match the intended constants
    c1 = E1 - A + m*n
    c2 = E2 - B + n*p
    c3 = E3 - C + p*m
    k1 = base ** E1
    k2 = base ** E2
    k3 = base ** E3
    # Check that the magnitudes give two real solutions (A,B,C > 0 already by construction)
    t2 = (A * B) / float(C)
    s2 = (A * C) / float(B)
    r2 = (B * C) / float(A)
    if t2 <= 0 or s2 <= 0 or r2 <= 0:
        continue
    # Avoid nearly trivial cases where the reflection gives almost identical solutions
    if t2 < 1e-4 or s2 < 1e-4 or r2 < 1e-4:
        continue
    return {'base': base, 'k1': k1, 'k2': k2, 'k3': k3, 'm': m, 'n': n, 'p': p, 'c1': c1, 'c2': c2, 'c3': c3}
# Fallback (should be extremely rare)
base = 10; m = 2; n = 1; p = 3; A = 3; B = 4; C = 5; E1 = 2; E2 = 1; E3 = 3
c1 = E1 - A + m*n
c2 = E2 - B + n*p
c3 = E3 - C + p*m
k1 = base ** E1
k2 = base ** E2
k3 = base ** E3
return {'base': base, 'k1': k1, 'k2': k2, 'k3': k3, 'm': m, 'n': n, 'p': p, 'c1': c1, 'c2': c2, 'c3': c3}

    def verifier(assign):
import math
# Extract assignment
try:
    base = assign['base']
    k1 = assign['k1']
    k2 = assign['k2']
    k3 = assign['k3']
    m = assign['m']
    n = assign['n']
    p = assign['p']
    c1 = assign['c1']
    c2 = assign['c2']
    c3 = assign['c3']
except KeyError:
    return (False, None)  # missing keys
# Basic domain checks
if not (isinstance(base, int) and base > 1):
    return (False, None)
for v in [k1, k2, k3, m, n, p]:
    if not isinstance(v, int):
        return (False, None)
if k1 <= 0 or k2 <= 0 or k3 <= 0:
    return (False, None)
# Helper log-base function
def logb(x):
    return math.log(x) / math.log(base)
# Compute the three symmetric constants A,B,C from the instance
A = logb(k1) - c1 + m*n
B = logb(k2) - c2 + n*p
C = logb(k3) - c3 + p*m
# Ensure the structure yields two real solutions
if not (A > 0 and B > 0 and C > 0):
    return (False, None)
# Magnitudes for the shifted variables
try:
    t = math.sqrt(A * B / C)
    s = math.sqrt(A * C / B)
    r = math.sqrt(B * C / A)
except ValueError:
    return (False, None)  # non-real magnitudes
# Construct the two solutions in terms of u = log_b x, v = log_b y, w = log_b z
u_plus = n + s
v_plus = m + t
w_plus = p + r
u_minus = n - s
v_minus = m - t
w_minus = p - r
# Map to (x,y,z)
def bpow(exp):
    return base ** exp
x1 = bpow(u_plus); y1 = bpow(v_plus); z1 = bpow(w_plus)
x2 = bpow(u_minus); y2 = bpow(v_minus); z2 = bpow(w_minus)
# Verify both solutions satisfy the system numerically
def ok(x, y, z):
    L1 = logb(k1 * (x ** m) * (y ** n)) - logb(x) * logb(y)
    L2 = logb(k2 * (y ** n) * (z ** p)) - logb(y) * logb(z)
    L3 = logb(k3 * (z ** p) * (x ** m)) - logb(z) * logb(x)
    tol = 1e-7
    return (abs(L1 - c1) <= tol and abs(L2 - c2) <= tol and abs(L3 - c3) <= tol)
if not ok(x1, y1, z1):
    return (False, None)
if not ok(x2, y2, z2):
    return (False, None)
# Ensure distinct solutions (nontrivial reflection)
if abs(y1 - y2) < 1e-12:
    return (False, None)
# Compute and cross-check the answer: y1*y2 should equal base^(2*m)
answer = base ** (2 * m)
prod = y1 * y2
# Relative check to guard against floating noise
if abs(prod - answer) / max(1.0, abs(answer)) > 1e-7:
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

